// vite.config.ts: the plugin scans source files and serves the CSS
import { defineConfig } from 'vite';
import tailwindcss from '@tailwindcss/vite';

export default defineConfig({
  plugins: [tailwindcss()],
});

/* src/input.css: one import brings in every utility and variant */
@import "tailwindcss";

/* Files outside the automatic scan must be listed explicitly */
@source "../templates/**/*.html";

/* app.css: switch the dark variant to a class instead of the OS setting */
@import "tailwindcss";

/* Now dark: matches .dark and anything inside it */
@custom-variant dark (&:where(.dark, .dark *));

// Run in <head> before first paint so the wrong theme never flashes
const stored = localStorage.getItem('theme');
const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

document.documentElement.classList.toggle('dark', stored ? stored === 'dark' : prefersDark);

// Call this from the theme switch
function setTheme(theme) {
  localStorage.setItem('theme', theme);
  document.documentElement.classList.toggle('dark', theme === 'dark');
}

/* app.css: v4 reads configuration from CSS, no tailwind.config.js */
@import "tailwindcss";

@theme {
  /* Tokens generate utilities: bg-brand-500, font-display, rounded-card */
  --color-brand-50: oklch(97% 0.02 200);
  --color-brand-500: oklch(62% 0.16 200);
  --color-brand-900: oklch(32% 0.09 200);

  --font-display: "Satoshi", system-ui, sans-serif;
  --radius-card: 1.25rem;
  --breakpoint-3xl: 120rem;
}

/* A custom utility still accepts variants such as hover: and lg: */
@utility content-auto {
  content-visibility: auto;
  contain-intrinsic-size: 800px;
}

/* Named component class built from utilities */
@layer components {
  .btn-primary {
    @apply inline-flex items-center gap-2 rounded-lg bg-cyan-600 px-4 py-2 text-sm font-semibold text-white hover:bg-cyan-700;
  }
}

/* Plugins load from CSS and can take their own options */
@plugin "@tailwindcss/typography";
@plugin "@tailwindcss/forms" {
  strategy: class;
}

/* Scan templates outside the entry point, skipping generated mail */
@source "../templates/**/*.html";
@source not "../templates/email";

// Variants live in one map; layout classes come from the caller
const styles = {
  base: 'inline-flex items-center justify-center gap-2 rounded-lg text-sm font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 disabled:opacity-50',
  primary: 'bg-cyan-600 text-white hover:bg-cyan-700 focus-visible:outline-cyan-600',
  ghost: 'text-slate-700 hover:bg-slate-100 focus-visible:outline-slate-400',
};

export function Button({ variant = 'primary', className = '', ...props }) {
  return <button className={`${styles.base} ${styles[variant]} ${className}`} {...props} />;
}
